import {bindCartTest} from './pf-cart-test.mjs?v=2';
import {proofQueue,proofQueueLabel} from './proof-status.mjs';
import {foilFinish} from './foil-options.mjs';
const $=id=>document.getElementById(id);let orders=[],selectedId=null,previewUrl=null;
const labels={prepared:'Klar til afsendelse',confirmed:'PF har bekræftet ordren',gateway_accepted:'Modtaget af PF',awaiting_proof:'Afventer korrektur',proof_received:'Korrektur klar',approval_pending_pf:'Godkendt · afventer PF',revision_requested:'Ændring ønsket',approval_recorded:'Godkendelse registreret hos PF',processing:'PF behandler ordren',shipped:'Afsendt',needs_attention:'Kræver opmærksomhed',needs_reconciliation:'Afstem med PF',cancelled:'Annulleret'};
function el(tag,txt,cls){const node=document.createElement(tag);if(txt!=null)node.textContent=String(txt);if(cls)node.className=cls;return node;}
function statusTone(order){if(['needs_attention','needs_reconciliation'].includes(order.status))return 'error';if(order.status==='revision_requested')return 'changes';if(['approval_pending_pf','approval_recorded','shipped'].includes(order.status))return 'approved';if(proofQueue(order)==='pf')return 'waiting';if(proofQueue(order)==='customer')return 'customer';return 'neutral';}
function badges(order){const group=el('div',null,'proof-badges');group.append(el('span',labels[order.status]||order.status,'pill tone-'+statusTone(order)));return group;}
function fold(title){const node=el('details',null,'proof-fold');node.append(el('summary',title));return node;}
function decisionCard(decision,title){const approved=decision.decision==='approve',card=el('section',null,'decision-card tone-'+(approved?'approved':'changes'));card.append(el('span',title,'decision-label'),el('h3',approved?'Godkendt':'Ændringer ønsket'));if(decision.at)card.append(el('small',new Date(decision.at).toLocaleString('da-DK')));if(decision.comment){const quote=el('blockquote',decision.comment);card.append(quote);}return card;}
function say(message){$('feedback').textContent=message||'';}
async function api(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',headers:{...(method!=='GET'?{'X-Smerch-Admin':'1'}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!response.ok){let problem;try{problem=await response.json();}catch{}throw Error(problem?.error||`HTTP ${response.status}`);}return response;}
async function refresh(){try{orders=await (await api('/api/pf-orders')).json();$('login').hidden=true;$('gateway-test').hidden=false;$('workspace').hidden=false;$('refresh').hidden=false;$('logout').hidden=false;renderList();if(selectedId)await show(selectedId);else if(orders[0])await show(orders[0].id);say('');}catch(error){say(error.message);if(error.message.includes('Administratoradgang')){$('login').hidden=false;$('gateway-test').hidden=true;$('workspace').hidden=true;$('refresh').hidden=true;$('logout').hidden=true;}}}
function renderList(){const area=$('orders');area.replaceChildren();const filter=$('filter').value,query=$('order-search').value.trim().toLocaleLowerCase('da');for(const order of orders.filter(row=>(filter==='all'||proofQueue(row)===filter)&&[row.purchaseOrderNumber,row.id,row.pfOrderNumber].filter(Boolean).join(' ').toLocaleLowerCase('da').includes(query))){const button=el('button',null,'order'+(order.id===selectedId?' active':''));button.type='button';button.setAttribute('aria-pressed',String(order.id===selectedId));button.append(el('strong',order.purchaseOrderNumber),badges(order),el('small',new Date(order.updatedAt).toLocaleString('da-DK')));button.onclick=()=>show(order.id);area.append(button);}if(!area.childElementCount)area.append(el('p','Ingen ordrer i dette filter.','muted'));}
async function show(id){selectedId=id;renderList();const order=await (await api(`/api/pf-orders/${id}`)).json(),checkout=order.checkoutId?await api(`/api/checkout/${order.checkoutId}`).then(response=>response.json()).catch(()=>null):null,box=$('detail');if(selectedId!==id)return;box.replaceChildren();if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}box.append(el('h2',order.purchaseOrderNumber),badges(order));const orderInfo=fold('Ordreoplysninger og originalfiler');if(checkout)orderInfo.append(el('p',`Smerch-ordre ${checkout.id} · betaling: ${checkout.status==='paid'?'hævet':checkout.status==='authorized'?'reserveret, ikke hævet':checkout.status}`,'muted'));
 if(order.decision){const card=decisionCard(order.decision,order.decision.actor==='customer'?'Kundens tilbagemelding':'Smerchs tilbagemelding');card.append(el('p',order.adminTest?'Test: Betaling og produktion er blokeret.':order.decision.delivery?.reference?'Sendt til PF. Afventer deres tilbagemelding.':order.decision.decision==='approve'?'Næste skridt: Afklar betaling, og send godkendelsen til PF.':'Næste skridt: Send ændringsønsket til PF, og indhent en ny korrektur.'));box.append(card);}
 const isTest=order.adminTest===true||order.gatewayPayload?.Header?.isTest===true,hasDecorations=order.lines?.some(line=>line.decorations?.length);if(isTest&&!order.decision)box.append(el('p',order.adminTest?'Intern korrekturtest · ingen betaling eller produktion':'PF-testordre · ingen betaling · kan ikke frigives til produktion','status ready'));
 const facts=el('div',null,'facts');for(const [label,value] of [['Miljø',order.adminTest?'Intern korrekturtest':isTest?'PF test':'PF produktion'],['PF-ordrenr.',order.pfOrderNumber||'Afventer PF-bekræftelse'],['Produkter',order.lines?.map(line=>line.productId).join(', ')||'—'],['Antal',order.lines?.reduce((sum,line)=>sum+line.quantity,0)||0],['Placeringer',order.lines?.reduce((sum,line)=>sum+line.decorations.length,0)||0],['Kundepris inkl. moms',order.quote?.totalIncVat!=null?(order.quote.totalIncVat/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'}):'—'],['Senest opdateret',new Date(order.updatedAt).toLocaleString('da-DK')]]){const card=el('div');card.append(el('span',label),el('strong',value));facts.append(card);}orderInfo.append(facts);for(const line of order.lines||[]){const section=el('section');section.append(el('h3',`${line.quantity} × ${line.productId} · ${line.sku}`));for(const decoration of line.decorations){section.append(el('p',`${decoration.method}${decoration.foilFinish?' · '+(foilFinish(decoration.foilFinish)?.label||''):''} · ${decoration.position} · ${decoration.colors} farve${decoration.colors===1?'':'r'} · ${decoration.width} × ${decoration.height} mm · ${decoration.pmsColors?.join(', ')||'Farver afventer'}`));if(decoration.text)section.append(el('p',`Tekst: ${decoration.text}`));for(const [artIndex,art] of (decoration.artworks||[]).entries()){const a=el('a',`Hent originalfil: ${art.logo.name} ↓`);a.href=order.checkoutId?`/api/admin/checkouts/${order.checkoutId}/artwork/${art.logo.id}`:decoration.files?.raw?.[artIndex]||'#';a.className='action light';section.append(a);}}orderInfo.append(section);}box.append(orderInfo);let history;if(order.proofs?.length){const section=fold(`Tidligere versioner og svar (${order.proofs.length})`);history=section;for(const proof of order.proofs){const a=el('a',`Version ${proof.version} · ${proof.reference} · ${new Date(proof.receivedAt).toLocaleString('da-DK')}`);a.href=proof.mimeType?`/api/pf-orders/${id}/proof-file?version=${proof.version}`:proof.url;a.target='_blank';a.rel='noopener noreferrer';section.append(a,document.createElement('br'));if(proof.decision){section.append(decisionCard(proof.decision,'Tilbagemelding · version '+proof.version));for(const file of proof.decision.attachments||[]){const attachment=el('a',`Bilag: ${file.name}`);attachment.href=`/api/pf-orders/${id}/feedback-file?hash=${file.hash}`;section.append(attachment,document.createElement('br'));}}}box.append(section);}
 if(order.proof){box.append(el('h2',`Korrektur version ${order.proof.version}`));box.append(el('p',`PF-reference: ${order.proof.reference}`));const preview=el('div',null,'preview');box.append(preview);if(order.proof.mimeType){try{const response=await api(`/api/pf-orders/${id}/proof-file?version=${order.proof.version}`),blob=await response.blob();previewUrl=URL.createObjectURL(blob);const media=document.createElement(order.proof.mimeType==='application/pdf'?'iframe':'img');media.src=previewUrl;media.title='PF-korrektur';preview.append(media);}catch(error){preview.append(el('p',error.message));}}else if(order.proof.url){const link=el('a','Åbn korrektur hos PF ↗');link.href=order.proof.url;link.target='_blank';link.rel='noopener noreferrer';preview.append(link);}}
 const actionStart=box.childElementCount;
 if(hasDecorations&&['gateway_accepted','awaiting_proof','proof_received','revision_requested','approval_pending_pf'].includes(order.status)){const section=el('section');section.append(el('h2','Tilføj korrektur'));const ref=el('input');ref.placeholder='PF-korrekturreferencen';ref.setAttribute('aria-label','PF-korrekturreferencen');const upload=el('input');upload.type='file';upload.accept='.pdf,.png,.jpg,.jpeg';upload.setAttribute('aria-label','Korrekturfil');const button=el('button','Gem korrektur');button.onclick=async()=>{try{if(!upload.files[0])throw Error('Vælg en korrekturfil.');const file=upload.files[0];if(file.size>10*1024*1024)throw Error('Filen må højst være 10 MB.');const contentBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});await api(`/api/pf-orders/${id}/proof`,'POST',{proofReference:ref.value,mimeType:file.type,contentBase64});await refresh();}catch(error){say(error.message);}};section.append(ref,upload,button);box.append(section);}
 if(order.checkoutId&&order.status==='proof_received'){
  const area=el('section');area.append(el('h2',order.proof.customer?'Afventer kundens svar':'Send til kundegodkendelse'));
  const note=el('textarea');note.placeholder='Forklar eventuelle rettelser, fx øget bogstavafstand.';note.setAttribute('aria-label','Besked til kunden');note.maxLength=2000;note.value=order.proof.customer?.message||'';
  const publish=el('button',order.proof.customer?'Send nyt personligt link':'Send korrektur til kunden','primary');publish.disabled=!order.proof.mimeType;
  publish.onclick=async()=>{publish.disabled=true;try{await api(`/api/pf-orders/${id}/publish`,'POST',{version:order.proof.version,message:note.value});await refresh();say('Korrekturen er lagt i mailkøen. Et tidligere link til denne version er erstattet.');}catch(error){say(error.message);publish.disabled=false;}};
  area.append(note,publish,el('p','Kunden modtager et personligt link. Automatisk påmindelse efter 2 og 4 dage, så længe korrekturen afventer svar. Ny pris eller levering skal afklares særskilt før godkendelse.','muted'));
  if(!order.proof.mimeType)area.append(el('p','Upload selve korrekturfilen først. Et eksternt PF-link kan ikke sendes som kundekorrektur.'));
  const mails=await (await api(`/api/pf-orders/${id}/mail-status`)).json();for(const mail of mails.filter(mail=>mail.version===order.proof.version))area.append(el('p',`Mail: ${mail.status} · sendt ${mail.sentCount} gang(e)${mail.lastSentAt?' · '+new Date(mail.lastSentAt).toLocaleString('da-DK'):''}${mail.error?' · '+mail.error:''}`,'muted'));
  box.append(area);
 }
 if(order.status==='proof_received'){const area=el('div');area.append(el('h2','Beslutning'));const note=el('textarea');note.placeholder='Kommentar til PF ved ændringsønske';note.setAttribute('aria-label','Kommentar til PF');const buttons=el('div',null,'actions');for(const [decision,text,cls] of [['approve','Godkend hos Smerch','primary'],['reject','Bed om ændring','danger']]){if(decision==='approve'&&order.checkoutId)continue;const button=el('button',text,cls);button.disabled=decision==='approve'&&checkout&&!['authorized','paid'].includes(checkout.status);button.onclick=async()=>{try{const result=await (await api(`/api/pf-orders/${id}/decision`,'POST',{version:order.proof.version,decision,comment:note.value})).json();await refresh();if(result.captureIssue)say(`Korrekturen er godkendt, men betalingen er ikke hævet: ${result.captureIssue}`);}catch(error){say(error.message);}};buttons.append(button);}area.append(note,buttons,el('p','Kunden godkender selv via sit personlige link. Her kan Smerch bede PF om en teknisk rettelse. Betaling og frigivelse håndteres særskilt.','muted'));box.append(area);}
 if(order.decision){for(const file of order.decision.attachments||[]){const link=el('a',`Hent kundens bilag: ${file.name}`);link.href=`/api/pf-orders/${id}/feedback-file?hash=${file.hash}`;box.append(link,document.createElement('br'));}}
 if(order.status==='shipped'&&checkout?.status==='authorized'&&order.lines.every(line=>!line.decorations?.length)){const capture=el('button','Hæv betaling for afsendte varer','primary');capture.onclick=async()=>{try{await api(`/api/admin/checkouts/${order.checkoutId}/capture`,'POST');await refresh();}catch(error){say(error.message);}};box.append(capture,el('p','Kan først hæves, når PF har bekræftet afsendelse for alle varer i ordren.','muted'));}
 if(order.status==='approval_pending_pf'&&checkout?.status==='authorized'){const capture=el('button','Hæv godkendt betaling','primary');capture.onclick=async()=>{try{await api(`/api/admin/checkouts/${order.checkoutId}/capture`,'POST');await refresh();}catch(error){say(error.message);}};box.append(capture,el('p','Hævning kræver, at alle PF-korrekturer for kundeordren er godkendt, og reservationen stadig er gyldig.','muted'));}
 if(order.status==='approval_pending_pf'||order.status==='revision_requested'){const area=el('section');area.append(el('h2','Besked til PF'));const copy=el('button','Kopiér beslutning');copy.disabled=Boolean(order.checkoutId&&order.decision.decision==='approve'&&checkout?.status!=='paid');copy.onclick=async()=>{const message=[`Smerch-ordre: ${order.purchaseOrderNumber}`,`PF-ordre: ${order.pfOrderNumber||'ukendt'}`,`Korrektur: ${order.proof.reference} (version ${order.proof.version})`,order.decision.decision==='approve'?'Beslutning: Vi godkender denne korrektur og ønsker produktionen bekræftet.':`Beslutning: Vi ønsker en ny korrektur. ${order.decision.comment}`,...(order.decision.attachments||[]).map(file=>`Bilag: ${file.name} (vedhæft manuelt)`),'Bekræft venligst modtagelse med jeres reference.'].join('\n');try{await navigator.clipboard.writeText(message);say('Beskeden er kopieret. Send den gennem den aftalte PF-kanal.');}catch{say('Kunne ikke kopiere. Brug PF’s aftalte kanal manuelt.');}};area.append(copy,el('p',copy.disabled?'Betalingen er endnu ikke hævet. Godkendelsen må ikke sendes til PF.':'Afsend gennem den aftalte PF-kanal. Denne knap sender ikke automatisk noget til PF.','muted'));box.append(area);}
 if(['approval_pending_pf','revision_requested'].includes(order.status)&&(!order.checkoutId||order.decision?.decision==='reject'||checkout?.status==='paid')&&!order.decision.delivery?.reference){const area=el('section');area.append(el('h2',order.decision.decision==='approve'?'Registrér godkendelse sendt til PF':'Registrér ændringsønske sendt til PF'));const channel=el('select');for(const name of ['PF Store','E-mail','Anden aftalt PF-kanal']){const option=el('option',name);option.value=name;channel.append(option);}const reference=el('input');reference.placeholder='Afsendelsesreference eller besked-id';reference.setAttribute('aria-label','Afsendelsesreference');const button=el('button','Registrér afsendelse');button.onclick=async()=>{try{await api(`/api/pf-orders/${id}/approval-delivery`,'POST',{channel:channel.value,reference:reference.value});await refresh();}catch(error){say(error.message);}};area.append(channel,reference,button,el('p','Send først beslutningen gennem den aftalte PF-kanal. Registreringen sender ikke selv noget.','muted'));box.append(area);}if(order.decision?.delivery?.reference)box.append(el('p',`Godkendelse sendt via ${order.decision.delivery.channel} · ${order.decision.delivery.reference}`));
 if(order.status==='approval_pending_pf'){const area=el('section');area.append(el('h2','PF-kvittering'));const reference=el('input');reference.placeholder='PF’s godkendelsesreference';reference.setAttribute('aria-label','PF’s godkendelsesreference');const button=el('button','Registrér bekræftelse fra PF');button.disabled=Boolean(order.checkoutId&&(checkout?.status!=='paid'||!order.decision.delivery?.reference));button.onclick=async()=>{try{await api(`/api/pf-orders/${id}/external-approval`,'POST',{pfApprovalReference:reference.value});await refresh();}catch(error){say(error.message);}};area.append(reference,button,el('p','Brug kun dette felt, når PF faktisk har kvitteret for godkendelsen, og kundens betaling er hævet.','muted'));box.append(area);}
 const actionNodes=[...box.children].slice(actionStart);if(actionNodes.length){const actions=fold('Handlinger og kommunikation med PF');actions.append(...actionNodes);box.append(actions);}box.append(orderInfo);if(history)box.append(history);const events=fold('Hændelseslog');box.append(events);for(const event of [...(order.events||[])].reverse()){events.append(el('div',`${new Date(event.at).toLocaleString('da-DK')} · ${event.type}${event.version?` · version ${event.version}`:''}`,'event'));}}
const cartTest=bindCartTest();
$('gateway-test-form').onsubmit=async event=>{event.preventDefault();const button=$('send-gateway-test');if($('test-confirmation').value!=='TEST'){say('Skriv TEST præcis som vist for at sende testordren.');return;}button.disabled=true;button.setAttribute('aria-busy','true');say('Sender testordren til PF’s testmiljø …');try{const shipping={name:$('test-name').value.trim(),email:$('test-email').value.trim(),phone:$('test-phone').value.trim(),street:$('test-street').value.trim(),postalCode:$('test-postal').value.trim(),city:$('test-city').value.trim()},isCart=$('test-source').value==='cart',body=isCart?await cartTest.payload(shipping):{...shipping,confirmation:'TEST'};const result=await (await api(isCart?'/api/pf-orders/test-cart':'/api/pf-orders/test','POST',body)).json();$('test-confirmation').value='';await refresh();selectedId=result.id;await show(result.id);say(result.status==='gateway_accepted'?`Testordren ${result.purchaseOrderNumber} er modtaget af PF’s test-Gateway. Ingen betaling er oprettet.`:`Testordren ${result.purchaseOrderNumber} har status ${labels[result.status]||result.status}. Den er ikke sendt igen. Afstem med PF ved tvivl.`);}catch(error){await refresh().catch(()=>{});say(error.message);}finally{button.disabled=false;button.removeAttribute('aria-busy');}};
$('login').onsubmit=async event=>{event.preventDefault();try{await api('/api/admin/login','POST',{username:$('username').value.trim(),password:$('password').value});$('password').value='';await refresh();}catch(error){$('password').value='';say(error.message);}};$('refresh').onclick=refresh;$('logout').onclick=async()=>{try{await api('/api/admin/logout','POST');}finally{location.href='/';}};$('filter').onchange=renderList;$('order-search').oninput=renderList;api('/api/admin/session').then(response=>response.json()).then(state=>{if(state.authenticated)refresh();}).catch(()=>{});
